import React, { useRef, useState } from "react";
import { motion } from "framer-motion";
import axios from "axios";
import { Camera, UploadCloud, StopCircle, CheckCircle2, XCircle } from "lucide-react";

const Interview = () => {
  const videoRef = useRef(null);
  const mediaRecorderRef = useRef(null);
  const [recordedChunks, setRecordedChunks] = useState([]);
  const [recording, setRecording] = useState(false);
  const [uploading, setUploading] = useState(false);
  const [status, setStatus] = useState("");
  const [message, setMessage] = useState("");

  const startRecording = async () => {
    try {
      const stream = await navigator.mediaDevices.getUserMedia({ video: true, audio: true });
      videoRef.current.srcObject = stream;
      const mediaRecorder = new MediaRecorder(stream);
      mediaRecorderRef.current = mediaRecorder;
      mediaRecorder.start();
      setRecording(true);
      const chunks = [];
      mediaRecorder.ondataavailable = (e) => {
        if (e.data.size > 0) chunks.push(e.data);
      };
      mediaRecorder.onstop = () => {
        const blob = new Blob(chunks, { type: "video/webm" });
        setRecordedChunks([blob]);
        stream.getTracks().forEach((track) => track.stop());
      };
    } catch (err) {
      console.error("Error accessing webcam:", err);
      setMessage("❌ Cannot access webcam");
    }
  };

  const stopRecording = () => {
    if (mediaRecorderRef.current) {
      mediaRecorderRef.current.stop();
      setRecording(false);
    }
  };

  const handleUpload = async () => {
    if (recordedChunks.length === 0) {
      setMessage("Please record a video first!");
      return;
    }
    const videoBlob = recordedChunks[0];
    const formData = new FormData();
    formData.append("file", videoBlob, "interview.webm");

    try {
      setUploading(true);
      const res = await axios.post("http://localhost:8080/api/video/upload", formData, {
        headers: { "Content-Type": "multipart/form-data" },
      });
      setStatus("success");
      setMessage("✅ Video uploaded successfully!");
    } catch (err) {
      console.error(err);
      setStatus("error");
      setMessage("❌ Upload failed!");
    } finally {
      setUploading(false);
    }
  };

  return (
    <motion.div
      initial={{ opacity: 0, y: 40 }}
      animate={{ opacity: 1, y: 0 }}
      transition={{ duration: 0.6 }}
      className="min-h-[80vh] flex flex-col items-center justify-center bg-gradient-to-br from-indigo-50 to-blue-100 p-8"
    >
      <motion.h1
        initial={{ y: -20, opacity: 0 }}
        animate={{ y: 0, opacity: 1 }}
        transition={{ delay: 0.2 }}
        className="text-3xl font-bold text-blue-700 mb-6"
      >
        Practice Your Interview
      </motion.h1>

      <div className="bg-white shadow-xl rounded-2xl p-8 w-full max-w-lg flex flex-col items-center">
        <video
          ref={videoRef}
          className="w-full h-64 bg-black rounded-lg mb-4 object-cover"
          autoPlay
          muted
        ></video>

        <div className="flex space-x-4 mb-6">
          {!recording ? (
            <motion.button
              whileHover={{ scale: 1.05 }}
              whileTap={{ scale: 0.95 }}
              onClick={startRecording}
              className="flex items-center gap-2 bg-green-600 text-white px-6 py-2 rounded-md hover:bg-green-700 transition"
            >
              <Camera className="w-5 h-5" /> Start Recording
            </motion.button>
          ) : (
            <motion.button
              whileHover={{ scale: 1.05 }}
              whileTap={{ scale: 0.95 }}
              onClick={stopRecording}
              className="flex items-center gap-2 bg-red-600 text-white px-6 py-2 rounded-md hover:bg-red-700 transition"
            >
              <StopCircle className="w-5 h-5" /> Stop
            </motion.button>
          )}

          <motion.button
            whileHover={{ scale: 1.05 }}
            whileTap={{ scale: 0.95 }}
            disabled={uploading}
            onClick={handleUpload}
            className={`flex items-center gap-2 px-6 py-2 rounded-md transition ${
              uploading ? "bg-gray-400" : "bg-blue-600 hover:bg-blue-700 text-white"
            }`}
          >
            <UploadCloud className="w-5 h-5" /> {uploading ? "Uploading..." : "Upload"}
          </motion.button>
        </div>

        {status === "success" && (
          <div className="flex items-center text-green-600 gap-2">
            <CheckCircle2 className="w-5 h-5" /> {message}
          </div>
        )}
        {status === "error" && (
          <div className="flex items-center text-red-600 gap-2">
            <XCircle className="w-5 h-5" /> {message}
          </div>
        )}
        {!status && message && <p className="text-gray-700">{message}</p>}
      </div>
    </motion.div>
  );
};

export default Interview;
